create policy payments_select on payments for select to authenticated using (project_can(project_id, 'finance.view'));
create policy payments_insert on payments for insert to authenticated with check (exists (select 1 from unnest(array['finance.manage', 'finance.pay']) c where project_can(project_id, c)));
create policy payments_update on payments for update to authenticated using (exists (select 1 from unnest(array['finance.manage', 'finance.pay']) c where project_can(project_id, c)))
  with check (exists (select 1 from unnest(array['finance.manage', 'finance.pay']) c where project_can(project_id, c)));
create policy payments_delete on payments for delete to authenticated using (exists (select 1 from unnest(array['finance.manage', 'finance.pay']) c where project_can(project_id, c)));

create table tasks (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  data jsonb not null default '{}',
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index on tasks (project_id);
create trigger t_tasks before update on tasks for each row execute function touch_updated_at();
alter table tasks enable row level security;
create policy tasks_select on tasks for select to authenticated using (project_can(project_id, 'tasks.view'));
create policy tasks_insert on tasks for insert to authenticated with check (exists (select 1 from unnest(array['tasks.manage']) c where project_can(project_id, c)));
create policy tasks_update on tasks for update to authenticated using (exists (select 1 from unnest(array['tasks.manage']) c where project_can(project_id, c)))
  with check (exists (select 1 from unnest(array['tasks.manage']) c where project_can(project_id, c)));
create policy tasks_delete on tasks for delete to authenticated using (exists (select 1 from unnest(array['tasks.manage']) c where project_can(project_id, c)));

