create policy events_insert on events for insert to authenticated with check (exists (select 1 from unnest(array['calendar.view']) c where project_can(project_id, c)));
create policy events_update on events for update to authenticated using (exists (select 1 from unnest(array['calendar.view']) c where project_can(project_id, c)))
  with check (exists (select 1 from unnest(array['calendar.view']) c where project_can(project_id, c)));
